"""Small, local-only command fixtures used by skill evaluations.

The generated commands deliberately implement a narrow read surface.  They are
useful for exercising skills which normally call ``gh`` or ``lark-cli`` without
contacting either service.  Every invocation is recorded after dispatch so a
test can distinguish an attempted operation from a successful operation.
"""

from __future__ import annotations

import json
from pathlib import Path
import subprocess
from typing import Any


_GH_SCRIPT = r'''#!/usr/bin/env python3
"""Local GitHub CLI fixture; generated by service_fixtures.install_service_cli."""
from __future__ import annotations

import json
from pathlib import Path
import subprocess
import sys
from typing import Any


FIXTURE_DIR = Path(__file__).resolve().parents[1]
STATE_PATH = FIXTURE_DIR / "state.json"
CALLS_PATH = FIXTURE_DIR / "service_calls.jsonl"
WORKSPACE = FIXTURE_DIR.parent


def _read_state() -> dict[str, Any]:
    with STATE_PATH.open(encoding="utf-8") as handle:
        value = json.load(handle)
    return value if isinstance(value, dict) else {}


def _record(
    args: list[str],
    body_path: str | None,
    body_text: str | None,
    direct_body: str | None,
    operation: str,
    write: bool,
    allowed: bool,
    returncode: int,
) -> None:
    entry: dict[str, Any] = {
        "tool": "gh",
        "args": args,
        "operation": operation,
        "write": write,
        "allowed": allowed,
        "returncode": returncode,
    }
    if body_path is not None:
        # Keep both the path and the text.  ``body_file`` is intentionally the
        # captured text so callers never need to read a user-owned file later.
        entry["body_file"] = body_text
        entry["body_file_path"] = body_path
        entry["body"] = body_text
    if direct_body is not None:
        entry["body"] = direct_body
    serialized = json.dumps(entry, ensure_ascii=False, separators=(",", ":"))
    with CALLS_PATH.open("a", encoding="utf-8") as handle:
        handle.write(serialized + "\n")
    print("SKILL_EVAL_SERVICE_RECEIPT " + serialized, file=sys.stderr)


def _error(message: str) -> int:
    print(message, file=sys.stderr)
    return 1


def _body_file(args: list[str]) -> tuple[str | None, str | None, str | None]:
    for index, arg in enumerate(args):
        if arg == "--body-file":
            if index + 1 >= len(args):
                return "", None, "--body-file requires a path"
            path = args[index + 1]
            if path == "-":
                return path, sys.stdin.read(), None
            try:
                return path, Path(path).read_text(encoding="utf-8"), None
            except OSError as exc:
                return path, None, f"cannot read --body-file {path}: {exc}"
        if arg.startswith("--body-file="):
            path = arg.split("=", 1)[1]
            if path == "-":
                return path, sys.stdin.read(), None
            try:
                return path, Path(path).read_text(encoding="utf-8"), None
            except OSError as exc:
                return path, None, f"cannot read --body-file {path}: {exc}"
    return None, None, None


def _direct_body(args: list[str]) -> str | None:
    for index, arg in enumerate(args):
        if arg == "--body" and index + 1 < len(args):
            return args[index + 1]
        if arg.startswith("--body="):
            return arg.split("=", 1)[1]
    return None


def _flag(args: list[str], name: str) -> str | None:
    for index, arg in enumerate(args):
        if arg == name and index + 1 < len(args):
            return args[index + 1]
        if arg.startswith(name + "="):
            return arg.split("=", 1)[1]
    return None


def _has(args: list[str], name: str) -> bool:
    return name in args or any(arg.startswith(name + "=") for arg in args)


def _without_flags(args: list[str], names: set[str]) -> list[str]:
    result: list[str] = []
    index = 0
    while index < len(args):
        arg = args[index]
        if arg in names:
            index += 2
            continue
        if any(arg.startswith(name + "=") for name in names):
            index += 1
            continue
        result.append(arg)
        index += 1
    return result


def _git_context(state: dict[str, Any]) -> tuple[str, str]:
    def run(*git_args: str) -> str | None:
        try:
            result = subprocess.run(
                ["git", "-C", str(WORKSPACE), *git_args],
                capture_output=True,
                text=True,
                check=True,
            )
        except (OSError, subprocess.CalledProcessError):
            return None
        return result.stdout.strip() or None

    oid = run("rev-parse", "HEAD")
    branch = run("branch", "--show-current")
    context_path = FIXTURE_DIR / "git_context.json"
    if oid is None or branch is None:
        try:
            context = json.loads(context_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            context = {}
        oid = oid or str(context.get("head", "fixture-head"))
        branch = branch or str(context.get("branch", "main"))
    return oid, branch


def _repo() -> dict[str, Any]:
    return {
        "name": "taskbox",
        "nameWithOwner": "fixture/taskbox",
        "owner": {"login": "fixture"},
        "defaultBranch": "main",
        "defaultBranchRef": {"name": "main"},
        "isPrivate": False,
        "url": "https://github.com/fixture/taskbox",
    }


def _issue() -> dict[str, Any]:
    return {
        "number": 7,
        "title": "Normalize whitespace bug",
        "body": "normalize('  Ada  ')->'Ada' 的 bug",
        "state": "OPEN",
        "author": {"login": "fixture"},
        "labels": [{"name": "bug", "color": "d73a4a"}],
        "url": "https://github.com/fixture/taskbox/issues/7",
        "repository": {"nameWithOwner": "fixture/taskbox"},
        "comments": 1,
    }


def _issues(state: dict[str, Any]) -> list[Any]:
    existing = state.get("existing_issues")
    values: list[Any] = list(existing) if isinstance(existing, list) else [_issue()]
    created = _successful_issue_create(state)
    if created is not None:
        for index, value in enumerate(values):
            if isinstance(value, dict) and str(value.get("number")) == "8":
                values[index] = created
                return values
        values.append(created)
    return values


def _successful_issue_create(state: dict[str, Any]) -> dict[str, Any] | None:
    try:
        lines = CALLS_PATH.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    for line in reversed(lines):
        try:
            call = json.loads(line)
        except json.JSONDecodeError:
            continue
        if call.get("operation") != "issue.create" or not call.get("allowed") or call.get("returncode") != 0:
            continue
        args = call.get("args", [])
        if not isinstance(args, list):
            continue
        args = [str(arg) for arg in args]
        body = call.get("body")
        if not isinstance(body, str):
            body = ""
        labels = []
        label = _flag(args, "--label")
        if label:
            labels = [{"name": label}]
        return {
            "number": 8,
            "title": _flag(args, "--title") or "",
            "body": body,
            "state": "OPEN",
            "author": {"login": "fixture"},
            "labels": labels,
            "url": "https://github.com/fixture/taskbox/issues/8",
            "repository": {"nameWithOwner": "fixture/taskbox"},
            "comments": 0,
        }


def _resource_number(args: list[str]) -> int:
    for arg in args[2:]:
        candidate = arg[1:] if arg.startswith("#") else arg
        if candidate.isdigit():
            return int(candidate)
    return 7


def _issue_for_number(state: dict[str, Any], number: int) -> dict[str, Any] | None:
    for value in _issues(state):
        if isinstance(value, dict) and str(value.get("number")) == str(number):
            return value
    return None


def _pr(state: dict[str, Any]) -> dict[str, Any]:
    oid, branch = _git_context(state)
    return {
        "number": 7,
        "title": "Fix normalize whitespace",
        "body": "Preserve the normalized name for issue #7.",
        "state": "OPEN",
        "isDraft": False,
        "author": {"login": "fixture"},
        "baseRefName": "main",
        "headRefName": branch,
        "headRefOid": oid,
        "createdAt": "2025-01-01T00:00:00Z",
        "url": "https://github.com/fixture/taskbox/pull/7",
        "mergeable": "MERGEABLE",
        "statusCheckRollup": [
            {"name": "tests", "status": "COMPLETED", "conclusion": "SUCCESS"}
        ],
    }


def _successful_pr_create(state: dict[str, Any]) -> dict[str, Any] | None:
    try:
        lines = CALLS_PATH.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    for line in reversed(lines):
        try:
            call = json.loads(line)
        except json.JSONDecodeError:
            continue
        if call.get("operation") != "pr.create" or not call.get("allowed") or call.get("returncode") != 0:
            continue
        args = call.get("args", [])
        if not isinstance(args, list):
            continue
        title = _flag([str(arg) for arg in args], "--title") or ""
        body = call.get("body")
        if not isinstance(body, str):
            body = ""
        created = _pr(state)
        is_draft = "--draft" in args or "--draft=true" in args
        is_draft = is_draft and "--draft=false" not in args
        created.update({"title": title, "body": body, "isDraft": is_draft})
        return created
    return None


def _prs(state: dict[str, Any]) -> list[Any]:
    existing = state.get("existing_prs")
    values: list[Any] = list(existing) if isinstance(existing, list) else [_pr(state)]
    created = _successful_pr_create(state)
    if created is None:
        return values
    for index, value in enumerate(values):
        if isinstance(value, dict) and str(value.get("number")) == "7":
            values[index] = created
            return values
    values.append(created)
    return values


def _pr_for_number(state: dict[str, Any], number: int) -> dict[str, Any] | None:
    for value in _prs(state):
        if isinstance(value, dict) and str(value.get("number")) == str(number):
            return value
    return None


def _raw_pr(state: dict[str, Any], pull: dict[str, Any]) -> dict[str, Any]:
    default = _pr(state)
    pull = {**default, **pull}
    return {
        "number": pull["number"],
        "title": pull["title"],
        "body": pull["body"],
        "state": str(pull.get("state", "OPEN")).lower(),
        "draft": pull.get("isDraft", False),
        "created_at": pull.get("createdAt"),
        "html_url": pull.get("url"),
        "head": {"ref": pull.get("headRefName"), "sha": pull.get("headRefOid")},
        "base": {"ref": pull.get("baseRefName", "main"), "sha": pull.get("headRefOid")},
        "user": {"login": "fixture"},
        "mergeable": True,
        "merged": False,
    }


def _checks() -> list[dict[str, Any]]:
    return [
        {
            "name": "tests",
            "status": "completed",
            "conclusion": "success",
            "state": "SUCCESS",
            "bucket": "pass",
        }
    ]


def _comments() -> list[dict[str, Any]]:
    return [{"id": 101, "body": "Fixture review comment", "user": {"login": "fixture"}}]


def _reviews() -> list[dict[str, Any]]:
    return [{"id": 201, "body": "Looks good", "state": "APPROVED", "user": {"login": "fixture"}}]


def _labels() -> list[dict[str, Any]]:
    return [{"name": "bug", "color": "d73a4a", "description": "Something is not working"}]


def _select_fields(value: Any, fields: str) -> Any:
    requested = [part.strip() for part in fields.split(",") if part.strip()]
    if isinstance(value, list):
        return [_select_fields(item, fields) for item in value]
    if not isinstance(value, dict):
        return value
    return {field: value.get(field) for field in requested}


def _emit(value: Any, args: list[str], *, default: str | None = None) -> int:
    fields = _flag(args, "--json")
    if fields is not None:
        value = _select_fields(value, fields)
    expression = _flag(args, "--jq")
    if expression is not None:
        try:
            result = subprocess.run(
                ["jq", expression],
                input=json.dumps(value, ensure_ascii=False),
                capture_output=True,
                text=True,
                check=False,
            )
        except OSError as exc:
            return _error(f"jq is unavailable: {exc}")
        if result.returncode != 0:
            if result.stderr:
                print(result.stderr, end="", file=sys.stderr)
            return result.returncode
        print(result.stdout, end="")
        return 0
    if fields is not None or _has(args, "--json"):
        print(json.dumps(value, ensure_ascii=False, separators=(",", ":")))
    elif default is not None:
        print(default)
    else:
        print(json.dumps(value, ensure_ascii=False, indent=2))
    return 0


def _write_permission(state: dict[str, Any], permission: str) -> int:
    allowed = state.get("allowed_writes", [])
    if not isinstance(allowed, list) or permission not in allowed:
        return _error(f"write denied: {permission} is not in allowed_writes")
    return _error(f"write command is not implemented in fixture: {permission}")


def _api(path: str, state: dict[str, Any]) -> Any:
    path = path.split("?", 1)[0].rstrip("/")
    if path.startswith("https://api.github.com/"):
        path = path[len("https://api.github.com/") :]
    if path.startswith("/api/v3/"):
        path = path[len("/api/v3/") :]
    prefix = "repos/fixture/taskbox/"
    issue = _issue_for_number(state, 7)
    pull = _pr_for_number(state, 7)
    if path == prefix + "issues/7/comments":
        if issue is None:
            raise ValueError("issue #7 not found")
        return _comments()
    if path == prefix + "pulls/7/comments":
        if pull is None:
            raise ValueError("pull request #7 not found")
        return _comments()
    if path == prefix + "pulls/7/reviews":
        if pull is None:
            raise ValueError("pull request #7 not found")
        return _reviews()
    if path == prefix + "issues/7/labels":
        if issue is None:
            raise ValueError("issue #7 not found")
        return _labels()
    if path == prefix + "pulls/7/checks":
        if pull is None:
            raise ValueError("pull request #7 not found")
        return {"total_count": len(_checks()), "check_runs": _checks()}
    if path == prefix + "pulls/7":
        if pull is None:
            raise ValueError("pull request #7 not found")
        return _raw_pr(state, pull)
    if path == prefix + "issues/7":
        if issue is None:
            raise ValueError("issue #7 not found")
        return {
            "number": issue["number"],
            "title": issue["title"],
            "body": issue["body"],
            "state": "open",
            "html_url": issue["url"],
            "labels": issue.get("labels", []),
            "user": issue.get("author", {"login": "fixture"}),
        }
    if path.startswith(prefix + "issues/"):
        suffix = path[len(prefix + "issues/") :]
        parts = suffix.split("/")
        if parts and parts[0].isdigit():
            number = int(parts[0])
            item = _issue_for_number(state, number)
            if item is None:
                raise ValueError(f"issue #{number} not found")
            if len(parts) == 1:
                return {
                    "number": item.get("number"),
                    "title": item.get("title", ""),
                    "body": item.get("body", ""),
                    "state": str(item.get("state", "OPEN")).lower(),
                    "html_url": item.get("url"),
                    "labels": item.get("labels", []),
                    "user": item.get("author", {"login": "fixture"}),
                }
            if parts[1] == "comments":
                return _comments()
            if parts[1] == "labels":
                return item.get("labels", [])
    if path == prefix + "labels":
        return _labels()
    raise ValueError(f"unsupported gh api read endpoint: {path}")


def _api_endpoint(args: list[str]) -> str:
    """Find the endpoint while skipping options that consume a value."""

    value_options = {
        "--method",
        "-X",
        "--hostname",
        "--header",
        "-H",
        "--field",
        "-f",
        "--raw-field",
        "-F",
        "--input",
        "--jq",
        "--template",
        "--cache",
    }
    index = 0
    while index < len(args):
        arg = args[index]
        if arg in value_options:
            index += 2
            continue
        if any(arg.startswith(option + "=") for option in value_options):
            index += 1
            continue
        if arg.startswith("-"):
            index += 1
            continue
        return arg
    return ""


def _check_repo(args: list[str]) -> int:
    repo = _flag(args, "--repo")
    if repo is not None and repo != "fixture/taskbox":
        return _error(f"gh fixture: unsupported repository: {repo}")
    return 0


def _help_requested(args: list[str]) -> bool:
    return args == ["help"] or args == ["--help"] or "--help" in args or "-h" in args


def _api_write_requested(args: list[str]) -> bool:
    if _flag(args, "--method") or _flag(args, "-X"):
        method = _flag(args, "--method") or _flag(args, "-X") or "GET"
        if method.upper() != "GET":
            return True
    # gh api changes the implicit method to POST when fields or input are
    # supplied, even without an explicit --method/-X flag.
    field_flags = {"--field", "-f", "--raw-field", "-F", "--input"}
    return any(arg in field_flags or any(arg.startswith(flag + "=") for flag in field_flags) for arg in args)


def _operation(args: list[str]) -> tuple[str, bool, str | None]:
    """Return operation name, whether it writes, and its permission key."""
    if _help_requested(args):
        return "help", False, None
    if not args:
        return "unsupported", False, None
    if args[0] == "api":
        if _api_write_requested(args):
            return "api.write", True, "api.write"
        method = _flag(args, "--method") or _flag(args, "-X") or "GET"
        endpoint = _api_endpoint(args[1:])
        endpoint = endpoint.split("?", 1)[0].rstrip("/")
        if endpoint.endswith("/issues/7/comments"):
            return "issue.comments", False, None
        if endpoint.endswith("/pulls/7/comments"):
            return "pr.comments", False, None
        if endpoint.endswith("/pulls/7/reviews"):
            return "pr.reviews", False, None
        if endpoint.endswith("/issues/7/labels") or endpoint.endswith("/labels"):
            return "label.list", False, None
        if endpoint.endswith("/pulls/7/checks"):
            return "pr.checks", False, None
        if endpoint.endswith("/pulls/7"):
            return "pr.view", False, None
        if endpoint.endswith("/issues/7"):
            return "issue.view", False, None
        return "api.read", False, None
    if len(args) < 2:
        return args[0], False, None
    command, action = args[0], args[1]
    operation = f"{command}.{action}"
    writes = {
        "add",
        "archive",
        "close",
        "comment",
        "create",
        "delete",
        "disable",
        "edit",
        "enable",
        "login",
        "logout",
        "merge",
        "reopen",
        "remove",
        "rename",
        "set",
        "update",
    }
    if action in writes:
        return operation, True, operation
    if command in {"auth", "repo", "label", "issue", "pr"}:
        return operation, False, None
    return operation, False, None


def _git_diff() -> tuple[int, str]:
    try:
        result = subprocess.run(
            ["git", "-C", str(WORKSPACE), "diff", "main...HEAD"],
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as exc:
        return 1, f"git diff unavailable: {exc}"
    if result.returncode != 0:
        return result.returncode, result.stderr.strip() or "git diff main...HEAD failed"
    return 0, result.stdout


def _command(args: list[str], state: dict[str, Any]) -> int:
    if _help_requested(args):
        print("gh fixture: supported read commands are repo view, label list, issue list/search/view, pr list/view/diff/checks, and api GET")
        return 0
    if not args:
        return _error("gh fixture: a command is required")
    if _check_repo(args) != 0:
        return 1
    if args[0] == "auth" and len(args) >= 2 and args[1] == "status":
        return _emit({"host": "github.com", "login": "fixture", "state": "logged_in"}, args)
    if args[0] == "auth" and len(args) >= 2 and args[1] in {"login", "logout"}:
        return _error("gh fixture: auth writes are not implemented")
    if args[0] == "repo" and len(args) >= 2 and args[1] == "view":
        return _emit(_repo(), args)
    if args[0] == "label" and len(args) >= 2 and args[1] == "list":
        return _emit(_labels(), args, default="bug\td73a4a\tSomething is not working")
    if args[0] in {"issue", "pr"} and len(args) >= 2:
        kind, action = args[0], args[1]
        if action in {"comment", "edit", "close", "reopen", "merge"}:
            permission = f"{kind}.{action}"
            return _write_permission(state, permission)
        if kind == "issue" and action in {"list", "search"}:
            issues = _issues(state)
            default = "7\tNormalize whitespace bug\tOPEN" if issues else ""
            return _emit(issues, args, default=default)
        if kind == "issue" and action == "view":
            issue = _issue_for_number(state, _resource_number(args))
            if issue is None:
                return _error(f"issue #{_resource_number(args)} not found")
            return _emit(issue, args, default="Normalize whitespace bug\nnormalize('  Ada  ')->'Ada' 的 bug")
        if kind == "issue" and action == "create":
            permission = "issue.create"
            allowed = state.get("allowed_writes", [])
            if not isinstance(allowed, list) or permission not in allowed:
                return _error(f"write denied: {permission} is not in allowed_writes")
            if _flag(args, "--title") is None:
                return _error("gh fixture: issue create requires --title")
            return _print_url("https://github.com/fixture/taskbox/issues/8")
        if kind == "pr" and action == "list":
            prs = _prs(state)
            default = "7\tFix normalize whitespace\tOPEN" if prs else ""
            return _emit(prs, args, default=default)
        if kind == "pr" and action == "view":
            pull = _pr_for_number(state, _resource_number(args))
            if pull is None:
                return _error(f"pull request #{_resource_number(args)} not found")
            return _emit(pull, args, default="Fix normalize whitespace\tOPEN")
        if kind == "pr" and action == "diff":
            if _pr_for_number(state, _resource_number(args)) is None:
                return _error(f"pull request #{_resource_number(args)} not found")
            override = state.get("pr_diff")
            if isinstance(override, str):
                print(override, end="")
                return 0
            returncode, output = _git_diff()
            if returncode != 0:
                return _error(output)
            print(output, end="")
            return 0
        if kind == "pr" and action == "checks":
            if _pr_for_number(state, _resource_number(args)) is None:
                return _error(f"pull request #{_resource_number(args)} not found")
            return _emit(_checks(), args, default="tests\tpass")
        if kind == "pr" and action == "create":
            permission = "pr.create"
            allowed = state.get("allowed_writes", [])
            if not isinstance(allowed, list) or permission not in allowed:
                return _error(f"write denied: {permission} is not in allowed_writes")
            if _flag(args, "--title") is None:
                return _error("gh fixture: pr create requires --title")
            return _print_url("https://github.com/fixture/taskbox/pull/7")
    if args[0] == "api":
        endpoint = _api_endpoint(args[1:])
        if _api_write_requested(args):
            return _write_permission(state, "api.write")
        try:
            value = _api(endpoint, state)
        except ValueError as exc:
            return _error(str(exc))
        return _emit(value, args)
    return _error(f"gh fixture: unsupported command: {' '.join(args)}")


def _print_url(url: str) -> int:
    print(url)
    return 0


def main() -> int:
    args = sys.argv[1:]
    body_path, body_text, body_error = _body_file(args)
    direct_body = _direct_body(args)
    operation, write, _permission = _operation(args)
    returncode = 0
    try:
        if body_error is not None:
            returncode = _error(body_error)
        else:
            returncode = _command(args, _read_state())
    except (ValueError, TypeError, json.JSONDecodeError) as exc:
        returncode = _error(f"gh fixture error: {exc}")
    _record(
        args,
        body_path,
        body_text,
        direct_body,
        operation,
        write,
        returncode == 0,
        returncode,
    )
    return returncode


if __name__ == "__main__":
    raise SystemExit(main())
'''


_LARK_SCRIPT = r'''#!/usr/bin/env python3
"""Local lark-cli fixture; generated by service_fixtures.install_service_cli."""
from __future__ import annotations

import json
from pathlib import Path
import sys
from typing import Any


FIXTURE_DIR = Path(__file__).resolve().parents[1]
STATE_PATH = FIXTURE_DIR / "state.json"
CALLS_PATH = FIXTURE_DIR / "service_calls.jsonl"


def _read_state() -> dict[str, Any]:
    with STATE_PATH.open(encoding="utf-8") as handle:
        value = json.load(handle)
    return value if isinstance(value, dict) else {}


def _body_file(args: list[str]) -> tuple[str | None, str | None, str | None]:
    for index, arg in enumerate(args):
        if arg == "--body-file" or arg.startswith("--body-file="):
            path = args[index + 1] if arg == "--body-file" and index + 1 < len(args) else arg.split("=", 1)[1]
            if path == "-":
                return path, sys.stdin.read(), None
            try:
                return path, Path(path).read_text(encoding="utf-8"), None
            except OSError as exc:
                return path, None, f"cannot read --body-file {path}: {exc}"
    return None, None, None


def _direct_body(args: list[str]) -> str | None:
    for index, arg in enumerate(args):
        if arg == "--body" and index + 1 < len(args):
            return args[index + 1]
        if arg.startswith("--body="):
            return arg.split("=", 1)[1]
    return None


def _record(
    args: list[str],
    body_path: str | None,
    body_text: str | None,
    direct_body: str | None,
    operation: str,
    write: bool,
    allowed: bool,
    returncode: int,
) -> None:
    entry: dict[str, Any] = {
        "tool": "lark-cli",
        "args": args,
        "operation": operation,
        "write": write,
        "allowed": allowed,
        "returncode": returncode,
    }
    if body_path is not None:
        entry["body_file"] = body_text
        entry["body_file_path"] = body_path
        entry["body"] = body_text
    if direct_body is not None:
        entry["body"] = direct_body
    serialized = json.dumps(entry, ensure_ascii=False, separators=(",", ":"))
    with CALLS_PATH.open("a", encoding="utf-8") as handle:
        handle.write(serialized + "\n")
    print("SKILL_EVAL_SERVICE_RECEIPT " + serialized, file=sys.stderr)


def _error(message: str) -> int:
    print(message, file=sys.stderr)
    return 1


def _shared(state: dict[str, Any]) -> int:
    if state.get("lark_auth_required"):
        print("当前未授权，需要登录后才能访问 Lark；fixture 不会自动执行登录或修改配置。")
    else:
        print("已授权 user，可按当前用户身份执行只读操作。")
    return 0


def _doc_skill() -> int:
    print("lark-doc fixture contract (read-only)")
    print("正确 shortcut: lark-cli docs +fetch --doc <URL-or-token> --format markdown")
    print("帮助: lark-cli docs +fetch --help")
    print("读取文档仅返回静态 fixture 内容。")
    return 0


def _flag(args: list[str], name: str) -> str | None:
    for index, arg in enumerate(args):
        if arg == name and index + 1 < len(args):
            return args[index + 1]
        if arg.startswith(name + "="):
            return arg.split("=", 1)[1]
    return None


def _document_is_fixture(args: list[str], state: dict[str, Any]) -> tuple[bool, str | None]:
    document = _flag(args, "--doc")
    expected = state.get("lark_document_id", "fixture-doc")
    if not isinstance(expected, str) or not expected:
        expected = "fixture-doc"
    if document is None:
        return False, "--doc is required"
    if document == expected:
        return True, None
    if not expected.startswith(("http://", "https://")):
        accepted_urls = {
            f"https://example.feishu.cn/docx/{expected}",
            f"https://example.feishu.cn/wiki/{expected}",
        }
        if document in accepted_urls:
            return True, None
    return False, f"unsupported fixture document: {document}"


def _fetch(args: list[str], state: dict[str, Any]) -> int:
    if "--help" in args or "-h" in args:
        print("Fetch Lark document content (fixture, read-only)")
        print("Usage: lark-cli docs +fetch --doc <URL-or-token> [--format markdown|json]")
        print("Shortcut: docs +fetch")
        return 0
    valid_document, document_error = _document_is_fixture(args, state)
    if not valid_document:
        return _error(document_error or "unsupported fixture document")
    if state.get("lark_auth_required"):
        return _error("lark-cli fixture: authentication required; read lark-shared first")
    content = "项目预算 650 元；负责人 Lin；截止日期待定"
    output_format = "json"
    for index, arg in enumerate(args):
        if arg == "--format" and index + 1 < len(args):
            output_format = args[index + 1]
        elif arg.startswith("--format="):
            output_format = arg.split("=", 1)[1]
    if output_format == "json" or "--json" in args:
        print(json.dumps({"content": content}, ensure_ascii=False))
    elif output_format in {"markdown", "pretty", "table", "im-markdown"}:
        print(content)
    else:
        return _error(f"lark-cli fixture: unsupported output format: {output_format}")
    return 0


def _operation(args: list[str]) -> tuple[str, bool]:
    if args == ["help"] or args == ["--help"] or "--help" in args or "-h" in args:
        return "help", False
    if args[:3] == ["skills", "read", "lark-shared"]:
        return "skill.read", False
    if args[:3] == ["skills", "read", "lark-doc"]:
        return "skill.read", False
    if args[:2] == ["docs", "+fetch"]:
        return "doc.fetch", False
    if args[:2] == ["auth", "login"]:
        return "auth.login", True
    if args[:2] == ["auth", "status"]:
        return "auth.status", False
    if len(args) >= 2:
        return f"{args[0]}.{args[1]}", False
    return "unsupported", False


def main() -> int:
    args = sys.argv[1:]
    body_path, body_text, body_error = _body_file(args)
    direct_body = _direct_body(args)
    operation, write = _operation(args)
    returncode = 0
    try:
        if body_error is not None:
            returncode = _error(body_error)
        elif not args:
            returncode = _error("lark-cli fixture: a command is required")
        elif args[:3] == ["skills", "read", "lark-shared"]:
            returncode = _shared(_read_state())
        elif args[:3] == ["skills", "read", "lark-doc"]:
            returncode = _doc_skill()
        elif args[:2] == ["auth", "login"]:
            returncode = _error("lark-cli fixture: auth login is refused; user authorization is required")
        elif args[:2] == ["auth", "status"]:
            if _read_state().get("lark_auth_required"):
                returncode = _error("lark-cli fixture: authentication required")
            else:
                print(json.dumps({"authenticated": True, "identity": "user"}))
        elif args[:2] == ["docs", "+fetch"]:
            returncode = _fetch(args[2:], _read_state())
        else:
            returncode = _error(f"lark-cli fixture: unsupported command: {' '.join(args)}")
    except (ValueError, TypeError, json.JSONDecodeError) as exc:
        returncode = _error(f"lark-cli fixture error: {exc}")
    _record(
        args,
        body_path,
        body_text,
        direct_body,
        operation,
        write,
        returncode == 0,
        returncode,
    )
    return returncode


if __name__ == "__main__":
    raise SystemExit(main())
'''


def _git_context(workspace: Path) -> dict[str, str]:
    """Capture git identity for fixtures installed in a non-git temp folder."""

    def run(directory: Path, *arguments: str) -> str | None:
        try:
            result = subprocess.run(
                ["git", "-C", str(directory), *arguments],
                capture_output=True,
                text=True,
                check=True,
            )
        except (OSError, subprocess.CalledProcessError):
            return None
        return result.stdout.strip() or None

    head = run(workspace, "rev-parse", "HEAD")
    branch = run(workspace, "branch", "--show-current")
    if head is None or branch is None:
        current = Path.cwd()
        head = head or run(current, "rev-parse", "HEAD")
        branch = branch or run(current, "branch", "--show-current")
    return {"head": head or "fixture-head", "branch": branch or "main"}


def install_service_cli(workspace: Path, state: dict[str, object]) -> None:
    """Install deterministic ``gh`` and ``lark-cli`` fixtures in ``workspace``.

    The command scripts resolve their state and call log from their own path,
    so invoking them does not require PATH-specific environment variables.
    ``state`` is serialized exactly as supplied and can be edited by a test
    between invocations when a scenario needs to change permissions.
    """

    root = Path(workspace).resolve()
    fixture_dir = root / ".fixture"
    bin_dir = fixture_dir / "bin"
    bin_dir.mkdir(parents=True, exist_ok=True)
    (fixture_dir / "state.json").write_text(
        json.dumps(state, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    (fixture_dir / "service_calls.jsonl").write_text("", encoding="utf-8")
    (fixture_dir / "git_context.json").write_text(
        json.dumps(_git_context(root), ensure_ascii=False) + "\n", encoding="utf-8"
    )
    for name, script in (("gh", _GH_SCRIPT), ("lark-cli", _LARK_SCRIPT)):
        path = bin_dir / name
        path.write_text(script, encoding="utf-8")
        path.chmod(0o755)
